// İnternet saati: ESP32 saati NTP ile internetten alır, OLED'de büyük rakamla gösterir.
#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <time.h>

const char* AG_ADI = "EvimWiFi";      // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";     // kendi Wi-Fi parolan
const char* NTP_SUNUCU = "pool.ntp.org";
const long SAAT_DILIMI = 3 * 3600;    // Türkiye: UTC+3 (saniye)
const unsigned long BAGLANTI_BEKLE_MS = 15000;  // açılışta Wi-Fi için en çok bu kadar bekle
const unsigned long YENIDEN_DENE_MS = 10000;    // Wi-Fi koparsa bu aralıkla yeniden dene
const int SDA_PIN = 21;
const int SCL_PIN = 22;

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
// OLED yazı tipinde Türkçe harf yok; gün adları ASCII.
const char* GUNLER[] = {"Paz", "Pzt", "Sal", "Car", "Per", "Cum", "Cmt"};
unsigned long sonDeneme = 0;
int sonDakika = -1;

void wifiBaslat() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  sonDeneme = millis();
}

void setup() {
  Serial.begin(115200);
  Wire.begin(SDA_PIN, SCL_PIN);
  if (!ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED bulunamadi. Kablolari ve 0x3C adresini kontrol et.");
    while (true) delay(1000);
  }
  ekran.setTextColor(SSD1306_WHITE);
  ekran.clearDisplay();
  ekran.setCursor(0, 0);
  ekran.println("Wi-Fi baglaniyor...");
  ekran.display();

  wifiBaslat();
  Serial.print("Wi-Fi'ye baglaniyor");
  while (WiFi.status() != WL_CONNECTED && millis() - sonDeneme < BAGLANTI_BEKLE_MS) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("Baglandi. IP: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("Baglanamadi. Arka planda yeniden denenecek.");
  }
  // Saat internetten (NTP) alınır; ESP32 sonra kendi sayar.
  configTime(SAAT_DILIMI, 0, NTP_SUNUCU);
}

void loop() {
  bool bagli = WiFi.status() == WL_CONNECTED;
  if (!bagli && millis() - sonDeneme > YENIDEN_DENE_MS) {
    Serial.println("Wi-Fi yok. Yeniden baglaniyor...");
    WiFi.disconnect();
    wifiBaslat();
  }

  ekran.clearDisplay();
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  if (bagli) {
    ekran.print("WiFi: bagli ");
    ekran.print(WiFi.RSSI());
    ekran.print(" dBm");
  } else {
    ekran.print("WiFi: yok");
  }
  ekran.drawFastHLine(0, 10, 128, SSD1306_WHITE);

  struct tm saat;
  if (getLocalTime(&saat, 100)) {
    char metin[16];
    // Saat ve dakika büyük (3 kat), saniye orta boy (2 kat).
    ekran.setTextSize(3);
    ekran.setCursor(2, 20);
    snprintf(metin, sizeof metin, "%02d:%02d", saat.tm_hour, saat.tm_min);
    ekran.print(metin);
    ekran.setTextSize(2);
    ekran.setCursor(92, 27);
    snprintf(metin, sizeof metin, ":%02d", saat.tm_sec);
    ekran.print(metin);

    // Alt satır: tarih ve gün, ortalı.
    ekran.setTextSize(1);
    ekran.setCursor(19, 54);
    snprintf(metin, sizeof metin, "%02d.%02d.%04d", saat.tm_mday, saat.tm_mon + 1, saat.tm_year + 1900);
    ekran.print(metin);
    ekran.print("  ");
    ekran.print(GUNLER[saat.tm_wday]);

    if (saat.tm_min != sonDakika) {
      sonDakika = saat.tm_min;
      Serial.printf("Saat %02d:%02d  Tarih %02d.%02d.%04d\n", saat.tm_hour, saat.tm_min,
                    saat.tm_mday, saat.tm_mon + 1, saat.tm_year + 1900);
    }
  } else {
    ekran.setCursor(10, 30);
    ekran.print("Saat bekleniyor...");
  }
  ekran.display();
  delay(200);
}
